package config

import (
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

// ScanTechnique is a TCP scan technique supported by nmap.
type ScanTechnique int

const (
	NotSupportTechnique ScanTechnique = iota
	TCPSYN
	TCPConnect
	TCPACK
	TCPWindow
	TCPMaimon
	TCPNull
	TCPFIN
	TCPXmas
)

// String returns the nmap option without its leading dash.
func (t ScanTechnique) String() string {
	switch t {
	case TCPSYN:
		return "sS"
	case TCPConnect:
		return "sT"
	case TCPACK:
		return "sA"
	case TCPWindow:
		return "sW"
	case TCPMaimon:
		return "sM"
	case TCPNull:
		return "sN"
	case TCPFIN:
		return "sF"
	case TCPXmas:
		return "sX"
	default:
		return "NotSupportTechnique"
	}
}

// PortScanConf configures an external scanner on the Vuls host.
type PortScanConf struct {
	ScannerBinPath       string   `toml:"scannerBinPath" json:"scannerBinPath,omitempty"`
	ScanTechniques       []string `toml:"scanTechniques" json:"scanTechniques,omitempty"`
	HasPrivileged        bool     `toml:"hasPrivileged" json:"hasPrivileged,omitempty"`
	SourcePort           string   `toml:"sourcePort" json:"sourcePort,omitempty"`
	IsUseExternalScanner bool     `toml:"-" json:"-"`
}

// IsZero reports whether no port scan setting was supplied.
func (c PortScanConf) IsZero() bool {
	return c.ScannerBinPath == "" && len(c.ScanTechniques) == 0 && c.SourcePort == "" && !c.HasPrivileged
}

// GetScanTechniques resolves configured nmap option codes without case sensitivity.
// Unsupported entries are represented once by NotSupportTechnique.
func (c *PortScanConf) GetScanTechniques() []ScanTechnique {
	if c == nil || len(c.ScanTechniques) == 0 {
		return []ScanTechnique{}
	}
	techniques := make([]ScanTechnique, 0, len(c.ScanTechniques))
	unsupported := false
	for _, value := range c.ScanTechniques {
		technique := parseScanTechnique(value)
		if technique == NotSupportTechnique {
			if unsupported {
				continue
			}
			unsupported = true
		}
		techniques = append(techniques, technique)
	}
	return techniques
}

func parseScanTechnique(value string) ScanTechnique {
	switch strings.ToLower(value) {
	case "ss":
		return TCPSYN
	case "st":
		return TCPConnect
	case "sa":
		return TCPACK
	case "sw":
		return TCPWindow
	case "sm":
		return TCPMaimon
	case "sn":
		return TCPNull
	case "sf":
		return TCPFIN
	case "sx":
		return TCPXmas
	default:
		return NotSupportTechnique
	}
}

// Validate checks settings that would be passed to an external scanner.
func (c PortScanConf) Validate() (errs []error) {
	if c.IsZero() && !c.IsUseExternalScanner {
		return nil
	}

	pathValid := false
	if c.ScannerBinPath == "" {
		errs = append(errs, fmt.Errorf("portscan.scannerBinPath is required for external scanning"))
	} else if info, err := os.Stat(c.ScannerBinPath); err != nil {
		errs = append(errs, fmt.Errorf("portscan.scannerBinPath %q: %w", c.ScannerBinPath, err))
	} else if !info.Mode().IsRegular() || info.Mode().Perm()&0111 == 0 {
		errs = append(errs, fmt.Errorf("portscan.scannerBinPath %q must be an executable file", c.ScannerBinPath))
	} else {
		pathValid = true
	}

	if len(c.ScanTechniques) > 1 {
		errs = append(errs, fmt.Errorf("portscan.scanTechniques: multiple scan techniques are not supported"))
	}
	for _, value := range c.ScanTechniques {
		technique := parseScanTechnique(value)
		if technique == NotSupportTechnique {
			errs = append(errs, fmt.Errorf("portscan.scanTechniques: unsupported technique %q", value))
		} else if !c.HasPrivileged && technique != TCPConnect {
			errs = append(errs, fmt.Errorf("portscan.scanTechniques: %s requires hasPrivileged = true; only sT is allowed without privileges", technique))
		}
	}

	if c.SourcePort != "" {
		port, err := strconv.Atoi(c.SourcePort)
		if err != nil || port < 0 || port > 65535 {
			errs = append(errs, fmt.Errorf("portscan.sourcePort %q must be an integer from 1 to 65535", c.SourcePort))
		} else if port == 0 {
			errs = append(errs, fmt.Errorf("portscan.sourcePort 0 is not a usable source port"))
		}
		if len(c.ScanTechniques) == 0 && !c.HasPrivileged || len(c.ScanTechniques) == 1 && parseScanTechnique(c.ScanTechniques[0]) == TCPConnect {
			errs = append(errs, fmt.Errorf("portscan.sourcePort cannot be used with TCPConnect (sT)"))
		}
	}

	if c.HasPrivileged && pathValid && os.Geteuid() != 0 {
		if err := checkScannerCapabilities(c.ScannerBinPath); err != nil {
			errs = append(errs, fmt.Errorf("portscan.scannerBinPath %q: %w", c.ScannerBinPath, err))
		}
	}
	return errs
}

// checkScannerCapabilities checks the effective file capabilities needed for raw TCP scans.
func checkScannerCapabilities(path string) error {
	output, err := exec.Command("getcap", path).Output()
	if err != nil {
		return fmt.Errorf("could not check scanner capabilities with getcap: %w", err)
	}
	line := strings.TrimSpace(string(output))
	if line == "" {
		return fmt.Errorf("missing scanner capabilities: cap_net_raw and cap_net_admin are required")
	}
	if !strings.HasPrefix(line, path) {
		return fmt.Errorf("malformed scanner capability data: %q", line)
	}
	capabilities := strings.TrimSpace(strings.TrimPrefix(line, path))
	capabilities = strings.TrimSpace(strings.TrimPrefix(capabilities, "="))
	if capabilities == "" || strings.Contains(capabilities, "\n") {
		return fmt.Errorf("malformed scanner capability data: %q", line)
	}
	effective := map[string]bool{}
	for _, group := range strings.Fields(capabilities) {
		separator := strings.IndexAny(group, "=+")
		if separator <= 0 || separator == len(group)-1 {
			return fmt.Errorf("malformed scanner capability data: %q", line)
		}
		flags := group[separator+1:]
		for _, flag := range flags {
			if !strings.ContainsRune("eip", flag) {
				return fmt.Errorf("malformed scanner capability data: %q", line)
			}
		}
		for _, capability := range strings.Split(group[:separator], ",") {
			if !strings.HasPrefix(capability, "cap_") || len(capability) <= len("cap_") {
				return fmt.Errorf("malformed scanner capability data: %q", line)
			}
			if strings.Contains(flags, "e") {
				effective[capability] = true
			}
		}
	}
	if !effective["cap_net_raw"] || !effective["cap_net_admin"] {
		return fmt.Errorf("missing effective scanner capabilities: cap_net_raw and cap_net_admin are required")
	}
	return nil
}

package scanner

import (
	"encoding/xml"
	"fmt"
	"net"
	osExec "os/exec"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/future-architect/vuls/config"
)

// execPortsScan selects the scanner configured for this server.
func (l *base) execPortsScan(scanDestIPPorts map[string][]string) ([]string, error) {
	if conf := l.ServerInfo.PortScan; conf != nil && conf.IsUseExternalScanner {
		return l.execExternalPortScan(scanDestIPPorts)
	}
	return l.execNativePortScan(scanDestIPPorts)
}

func (l *base) shouldSkipPortScanIP(ip string) bool {
	parsed := net.ParseIP(ip)
	return parsed != nil && parsed.IsLoopback() && !isLocalExec(l.ServerInfo.Port, l.ServerInfo.Host)
}

func (l *base) execNativePortScan(scanDestIPPorts map[string][]string) ([]string, error) {
	listenIPPorts := []string{}
	for ip, ports := range scanDestIPPorts {
		if l.shouldSkipPortScanIP(ip) {
			continue
		}
		for _, port := range ports {
			conn, err := net.DialTimeout("tcp", net.JoinHostPort(ip, port), time.Second)
			if err != nil {
				continue
			}
			conn.Close()
			listenIPPorts = append(listenIPPorts, ip+":"+port)
		}
	}
	return listenIPPorts, nil
}

// setScanTechniques converts scan types into nmap command line options.
func setScanTechniques(techniques []config.ScanTechnique) ([]string, error) {
	if len(techniques) > 1 {
		return nil, fmt.Errorf("multiple scan techniques are not supported")
	}
	options := make([]string, 0, len(techniques))
	for _, technique := range techniques {
		if technique == config.NotSupportTechnique || technique < config.TCPSYN || technique > config.TCPXmas {
			return nil, fmt.Errorf("unsupported scan technique: %v", technique)
		}
		options = append(options, "-"+technique.String())
	}
	return options, nil
}

func formatNmapOptionsToString(options []string) string {
	return strings.Join(options, " ")
}

type nmapRun struct {
	XMLName xml.Name `xml:"nmaprun"`
	Hosts   []struct {
		Ports []struct {
			Protocol string `xml:"protocol,attr"`
			PortID   string `xml:"portid,attr"`
			State    struct {
				Value string `xml:"state,attr"`
			} `xml:"state"`
		} `xml:"ports>port"`
	} `xml:"host"`
}

func (l *base) execExternalPortScan(scanDestIPPorts map[string][]string) ([]string, error) {
	conf := l.ServerInfo.PortScan
	if conf == nil {
		return nil, fmt.Errorf("external port scan requires portscan configuration")
	}
	if errs := conf.Validate(); len(errs) != 0 {
		return nil, fmt.Errorf("invalid external port scan configuration: %v", errs)
	}

	techniques := conf.GetScanTechniques()
	if len(techniques) == 0 {
		if conf.HasPrivileged {
			techniques = []config.ScanTechnique{config.TCPSYN}
		} else {
			techniques = []config.ScanTechnique{config.TCPConnect}
		}
	}
	techniqueOptions, err := setScanTechniques(techniques)
	if err != nil {
		return nil, err
	}

	listenIPPorts := []string{}
	for ip, ports := range scanDestIPPorts {
		if l.shouldSkipPortScanIP(ip) || len(ports) == 0 {
			continue
		}
		parsedIP := net.ParseIP(ip)
		if parsedIP == nil {
			return nil, fmt.Errorf("invalid port scan destination IP %q", ip)
		}
		uniqPorts := map[string]bool{}
		for _, port := range ports {
			n, err := strconv.Atoi(port)
			if err != nil || n < 1 || n > 65535 {
				return nil, fmt.Errorf("invalid port scan destination port %q", port)
			}
			uniqPorts[strconv.Itoa(n)] = true
		}
		portList := make([]string, 0, len(uniqPorts))
		for port := range uniqPorts {
			portList = append(portList, port)
		}
		sort.Slice(portList, func(i, j int) bool {
			left, _ := strconv.Atoi(portList[i])
			right, _ := strconv.Atoi(portList[j])
			return left < right
		})

		options := []string{"-n", "-Pn", "-oX", "-"}
		if parsedIP.To4() == nil {
			options = append(options, "-6")
		}
		if conf.HasPrivileged {
			options = append(options, "--privileged")
		}
		options = append(options, techniqueOptions...)
		if conf.SourcePort != "" {
			options = append(options, "-g", conf.SourcePort)
		}
		options = append(options, "-p", strings.Join(portList, ","), ip)
		output, err := osExec.Command(conf.ScannerBinPath, options...).Output()
		if err != nil {
			if exitErr, ok := err.(*osExec.ExitError); ok {
				return nil, fmt.Errorf("port scanner %q %s failed: %w: %s", conf.ScannerBinPath, formatNmapOptionsToString(options), err, strings.TrimSpace(string(exitErr.Stderr)))
			}
			return nil, fmt.Errorf("port scanner %q %s failed: %w", conf.ScannerBinPath, formatNmapOptionsToString(options), err)
		}
		var result nmapRun
		if err := xml.Unmarshal(output, &result); err != nil {
			return nil, fmt.Errorf("failed to parse port scanner output for %s: %w", ip, err)
		}
		if len(result.Hosts) == 0 {
			return nil, fmt.Errorf("port scanner returned no host results for %s", ip)
		}
		for _, host := range result.Hosts {
			for _, port := range host.Ports {
				if port.Protocol != "tcp" || !uniqPorts[port.PortID] {
					continue
				}
				// ACK and stealth scans can report a reachable port as
				// unfiltered or open|filtered rather than open.
				if port.State.Value == "open" || port.State.Value == "unfiltered" || port.State.Value == "open|filtered" {
					listenIPPorts = append(listenIPPorts, ip+":"+port.PortID)
				}
			}
		}
	}
	return listenIPPorts, nil
}
package config

import (
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

func TestPortScanTechniques(t *testing.T) {
	codes := []string{"sS", "ST", "Sa", "sw", "SM", "sn", "SF", "sx"}
	want := []ScanTechnique{TCPSYN, TCPConnect, TCPACK, TCPWindow, TCPMaimon, TCPNull, TCPFIN, TCPXmas}
	got := (&PortScanConf{ScanTechniques: codes}).GetScanTechniques()
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("GetScanTechniques() = %v, want %v", got, want)
	}
	for i, technique := range got {
		if !strings.EqualFold(technique.String(), codes[i]) {
			t.Errorf("%v.String() = %q, want %q", technique, technique.String(), codes[i])
		}
	}
	if got := (&PortScanConf{}).GetScanTechniques(); len(got) != 0 {
		t.Errorf("empty scan techniques = %v", got)
	}
	if got := (&PortScanConf{ScanTechniques: []string{"bad", "invalid"}}).GetScanTechniques(); !reflect.DeepEqual(got, []ScanTechnique{NotSupportTechnique}) {
		t.Errorf("unsupported scan techniques = %v", got)
	}
	if got := (&PortScanConf{ScanTechniques: []string{"sT", "bad"}}).GetScanTechniques(); !reflect.DeepEqual(got, []ScanTechnique{TCPConnect, NotSupportTechnique}) {
		t.Errorf("mixed scan techniques = %v", got)
	}
}

func TestPortScanIsZero(t *testing.T) {
	if !(PortScanConf{}).IsZero() || !(PortScanConf{IsUseExternalScanner: true}).IsZero() {
		t.Fatal("unset port scan fields should be zero")
	}
	for _, conf := range []PortScanConf{
		{ScannerBinPath: "/usr/bin/nmap"},
		{ScanTechniques: []string{"sS"}},
		{SourcePort: "443"},
		{HasPrivileged: true},
	} {
		if conf.IsZero() {
			t.Errorf("%+v was reported as zero", conf)
		}
	}
}

func TestPortScanValidate(t *testing.T) {
	path := filepath.Join(t.TempDir(), "scanner")
	if err := os.WriteFile(path, []byte("#!/bin/sh\nexit 0\n"), 0755); err != nil {
		t.Fatal(err)
	}
	tests := []struct {
		name string
		conf PortScanConf
		want string
	}{
		{"native default", PortScanConf{}, ""},
		{"connect", PortScanConf{ScannerBinPath: path, ScanTechniques: []string{"St"}}, ""},
		{"missing path", PortScanConf{ScanTechniques: []string{"sT"}}, "scannerBinPath"},
		{"explicit empty path", PortScanConf{IsUseExternalScanner: true}, "scannerBinPath"},
		{"nonexistent path", PortScanConf{ScannerBinPath: path + "-missing"}, "scannerBinPath"},
		{"unsupported", PortScanConf{ScannerBinPath: path, ScanTechniques: []string{"sU"}}, "unsupported technique"},
		{"multiple", PortScanConf{ScannerBinPath: path, ScanTechniques: []string{"sT", "sT"}}, "multiple scan techniques"},
		{"unprivileged syn", PortScanConf{ScannerBinPath: path, ScanTechniques: []string{"sS"}}, "hasPrivileged"},
		{"connect source port", PortScanConf{ScannerBinPath: path, ScanTechniques: []string{"sT"}, SourcePort: "443"}, "TCPConnect"},
		{"zero source port", PortScanConf{ScannerBinPath: path, SourcePort: "0"}, "sourcePort 0"},
		{"out of range source port", PortScanConf{ScannerBinPath: path, SourcePort: "65536"}, "sourcePort"},
		{"invalid source port", PortScanConf{ScannerBinPath: path, SourcePort: "abc"}, "sourcePort"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			errs := tt.conf.Validate()
			if tt.want == "" && len(errs) != 0 {
				t.Fatalf("unexpected validation errors: %v", errs)
			}
			if tt.want != "" {
				found := false
				for _, err := range errs {
					found = found || strings.Contains(err.Error(), tt.want)
				}
				if !found {
					t.Errorf("validation errors %v do not contain %q", errs, tt.want)
				}
			}
		})
	}
}

func TestTOMLPortScanPerServer(t *testing.T) {
	old := Conf
	Conf = Config{}
	defer func() { Conf = old }()
	path := filepath.Join(t.TempDir(), "config.toml")
	content := `[servers.external]
host = "localhost"
port = "local"
[servers.external.portscan]
scannerBinPath = "/usr/bin/nmap"
scanTechniques = ["sT"]

[servers.native]
host = "localhost"
port = "local"
[servers.native.portscan]
scanTechniques = []

[servers.empty]
host = "localhost"
port = "local"
[servers.empty.portscan]
scannerBinPath = ""
`
	if err := os.WriteFile(path, []byte(content), 0600); err != nil {
		t.Fatal(err)
	}
	if err := (TOMLLoader{}).Load(path, ""); err != nil {
		t.Fatal(err)
	}
	if got := Conf.Servers["external"].PortScan; got == nil || !got.IsUseExternalScanner || !reflect.DeepEqual(got.GetScanTechniques(), []ScanTechnique{TCPConnect}) {
		t.Errorf("external port scan not loaded: %+v", got)
	}
	if got := Conf.Servers["native"].PortScan; got == nil || got.IsUseExternalScanner {
		t.Errorf("native port scan incorrectly enabled: %+v", got)
	}
	if got := Conf.Servers["empty"].PortScan; got == nil || !got.IsUseExternalScanner {
		t.Errorf("explicit scannerBinPath was not enabled: %+v", got)
	}
}

func TestCheckPortScanConfig(t *testing.T) {
	server := ServerInfo{PortScan: &PortScanConf{ScanTechniques: []string{"sU"}}}
	server.Module.Set(Port)
	conf := Config{Servers: map[string]ServerInfo{"target": server}}
	if errs := conf.checkPortScanConfig(); len(errs) == 0 {
		t.Fatal("invalid port scan settings were accepted for a port scan target")
	}
	server.Module = ScanModule{}
	server.Module.Set(OSPkg)
	conf.Servers["target"] = server
	if errs := conf.checkPortScanConfig(); len(errs) != 0 {
		t.Errorf("port scan settings were checked without the port module: %v", errs)
	}
}

func TestCheckScannerCapabilities(t *testing.T) {
	dir := t.TempDir()
	getcap := filepath.Join(dir, "getcap")
	if err := os.WriteFile(getcap, []byte("#!/bin/sh\nprintf '%s\\n' \"$FAKE_CAP_OUTPUT\"\n"), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	path := filepath.Join(dir, "scanner")
